// Register server-side methods with s.post() / s.get() / s.put() / s.delete() / s.options() / s.query()
// (the client side is ../node_client/post_user.ts)
import { s } from '@comatype/typescript'
// path and s200 generated by `comatype generate` from post_user.comat ((noauth)/post_user.comat)
import { path, s200 } from '@/comatype/post_user'
import { db } from './db'

// Sign-up is called while logged out. The auth wrapper is disabled in (noauth)/defaults.comat
s.post(path, (req) => {
  // req.body is the data sent by the client (uid is not included). Already validated against the body schema
  const user = db.create({ name: req.body.name, email: req.body.email, phone: req.body.phone })
  // s200({ data }) builds a response with status 200
  return s200({ data: user })
})
